from lib import *
S = SS('n44')
steps = [
    step("ClientIP 的流程:① 如果设置了 TrustedPlatform 且该头非空,直接返回它;② 监听 unix socket 时一律信任;③ 否则取 RemoteAddr 的 IP,检查它是不是受信任代理(isTrustedProxy);④ 只有受信任时才去 RemoteIPHeaders(默认 X-Forwarded-For、X-Real-IP)里取,多行头用逗号拼起来;⑤ 取不到就返回 RemoteAddr 的 IP。从头里取用 validateHeader:从右往左遍历,遇到不是 IP 的就放弃,遇到不受信任的地址(或已经是第一项)就返回它。", t=tl(S(1)), mark=lidx(S(1), 'c.engine.TrustedPlatform != ""', 'strings.HasPrefix(localAddr.Network(), "unix")', 'c.engine.isTrustedProxy(remoteIP)', 'if (i == 0) || (!engine.isTrustedProxy(ip))'), done=lidx(S(1), 'strings.Join(c.Request.Header.Values(headerName), ",")', 'return remoteIP.String()', 'for i := len(items) - 1; i >= 0; i--'), kv=KV([['先判断', '远端是不是受信任代理'], ['再取头', 'XFF 从右往左跳过受信任地址'], ['TrustedPlatform', '优先级最高,直接返回']], ['先判断'])),
    step("默认配置(RemoteIPHeaders=[X-Forwarded-For X-Real-IP],ForwardedByClientIP=true,信任所有代理)下,直连的客户端想填什么就是什么:没有头 → 203.0.113.9(真实地址);自己加 X-Forwarded-For: 1.2.3.4 → ClientIP=1.2.3.4;XFF: 1.1.1.1, 2.2.2.2 → 1.1.1.1(取最左);只有 X-Real-IP → 5.5.5.5;XFF 与 X-Real-IP 都有 → 优先 XFF;XFF 不是 IP(unknown)→ 退到 X-Real-IP;XFF 带端口(1.2.3.4:5555)不是合法 IP → 退回 203.0.113.9;两行 XFF 头按逗号拼接。", t=tl(S(2)), mark=lidx(S(2), '自己伪造 XFF', 'XFF: 1.1.1.1, 2.2.2.2', '只有 X-Real-IP', 'XFF 不是 IP', 'XFF 带端口'), done=lidx(S(2), '直连,没有头', 'XFF 与 X-Real-IP 都有', '两行 XFF 头', 'IPv6 远端'), kv=KV([['默认', '信任所有代理:XFF 可伪造'], ['多个地址', '全是受信任时取最左一项'], ['非法 IP', '放弃该头,退到下一个头']], ['默认'])),
    step("SetTrustedProxies([\"10.0.0.0/8\", \"172.16.1.7\"]) 之后:攻击者直连(198.51.100.1)并伪造 XFF → 头被忽略,ClientIP=198.51.100.1;经过受信任代理 10.0.0.5、XFF: 203.0.113.7 → 203.0.113.7;攻击者伪造的 9.9.9.9 被代理追加了真实地址:9.9.9.9, 203.0.113.7 → 203.0.113.7(伪造的在左边,被丢弃);多层代理 203.0.113.7, 10.0.0.9, 10.0.0.8 → 从右往左跳过两个代理得 203.0.113.7;172.16.1.7 单个地址会被补成 /32,172.16.1.8 不在列表里,头被忽略;末项不是合法 IP → 退回 10.0.0.5。非法的配置返回 error(invalid CIDR address / invalid IP address);SetTrustedProxies(nil) 不信任任何代理,永远是 RemoteAddr。", t=tl(S(3)), mark=lidx(S(3), '攻击者直连并伪造 XFF', '攻击者伪造 + 代理追加', '172.16.1.8', 'invalid CIDR address', 'SetTrustedProxies(nil)'), done=lidx(S(3), '经受信任代理 10.0.0.5', '多层代理', '受信任的单个地址 172.16.1.7'), b=bars([['默认(信任所有)取到的 IP:伪造值', 1, '1.2.3.4(伪造成功)'], ['SetTrustedProxies 后:伪造值', 0, '被忽略']], 1, mark=[0], done=[1]), kv=KV([['从右往左', '跳过受信任代理,取第一个不受信任的'], ['不受信任的远端', '头被整个忽略'], ['配置错误', 'SetTrustedProxies 返回 error']], ['从右往左'])),
    step("RemoteIPHeaders 与 ForwardedByClientIP:同样的头(XFF 1.1.1.1、X-Real-IP 5.5.5.5、True-Client-IP 7.7.7.7),RemoteIPHeaders=[X-Real-IP] → 5.5.5.5;[True-Client-IP, X-Forwarded-For] → 7.7.7.7(按列表顺序取第一个有效的);ForwardedByClientIP=false 或 RemoteIPHeaders=nil → 只用 RemoteAddr(10.0.0.5)。", t=tl(S(4)), done=lidx(S(4), 'RemoteIPHeaders=[X-Real-IP]', 'True-Client-IP, X-Forwarded-For', 'ForwardedByClientIP=false', 'RemoteIPHeaders=nil'), kv=KV([['RemoteIPHeaders', '按列表顺序,取第一个有效的头'], ['ForwardedByClientIP=false', '完全不看头'], ['RemoteIPHeaders=nil', '同样不看头']], ['RemoteIPHeaders'])),
    step("TrustedPlatform(例如 Cloudflare 的 CF-Connecting-IP)不做任何检查:请求来自不受信任的 198.51.100.1,带 CF-Connecting-IP: 8.8.8.8,ClientIP 就是 8.8.8.8;头里写 not-an-ip 或 <script>,ClientIP 也原样返回这个字符串(没有 IP 格式校验);没有这个头时才回退到普通规则。只有确定服务只能经平台访问时才能设置它,否则任何人都能伪造。", t=tl(S(5)), mark=lidx(S(5), '8.8.8.8', 'not-an-ip', '<script>'), done=lidx(S(5), '没有这个头时', '常量'), kv=KV([['平台头', '原样返回,不看来源'], ['内容', '不校验是不是 IP'], ['风险', '直连源站时可被伪造']], ['风险'])),
]
A = mkartn('n44', 44, 'Gin,ClientIP,TrustedProxies,X-Forwarded-For,反向代理,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 ClientIP:默认信任所有代理,直连客户端伪造 X-Forwarded-For 就能指定 ClientIP;SetTrustedProxies 后从右往左跳过受信任代理、不受信任的远端头被忽略;RemoteIPHeaders 与 ForwardedByClientIP 的作用;TrustedPlatform 的头不做任何校验,原样返回。',
    '日志和限流里的客户端 IP 可信吗?默认配置下,任何人加一个 X-Forwarded-For 头就能改写 c.ClientIP()。这篇用伪造的请求把 Gin 取客户端 IP 的规则逐项验证:默认值、SetTrustedProxies、多层代理、头的优先级,以及 TrustedPlatform 的风险。',
    [('1.2.3.4', '默认配置下直连客户端伪造 X-Forwarded-For: 1.2.3.4 得到的 ClientIP(真实地址 203.0.113.9)'), ('203.0.113.7', '设置受信任代理后,XFF 为 9.9.9.9, 203.0.113.7 得到的 ClientIP——伪造的最左项被丢弃'), ('&lt;script&gt;', 'TrustedPlatform 下 CF-Connecting-IP 写成 &lt;script&gt; 时被原样返回为 ClientIP')],
    [('取 IP 的流程', '<p><code>ClientIP</code> 先看平台头(<code>TrustedPlatform</code>),再看是不是 unix socket,再判断远端是不是受信任代理,只有受信任才会去解析转发头;转发头从右往左处理。这个顺序决定了后面每一个结果。</p>'),
     ('默认是“信任所有”', '<p><code>gin.New()</code> 默认的受信任代理是 <code>0.0.0.0/0</code> 与 <code>::/0</code>,所以任何远端的 <code>X-Forwarded-For</code>、<code>X-Real-IP</code> 都被采信:不经过任何代理的直连客户端,自己写什么 IP 就是什么。debug 模式启动时会打印 “You trusted all proxies, this is NOT safe” 的警告,就是为了这个。</p>'),
     ('配置受信任代理', '<p>生产环境应当 <code>SetTrustedProxies</code> 成你自己的反向代理地址(或 CIDR;单个 IP 会补成 /32 或 /128)。之后只有来自这些地址的请求才会被解析转发头,并且从 <code>X-Forwarded-For</code> 的右端开始、跳过受信任的代理,取第一个不受信任的地址——代理链会在右边追加,客户端伪造的内容在左边,被丢弃。如果根本没有代理,设成 <code>nil</code>。</p>'),
     ('头的选择', '<p><code>RemoteIPHeaders</code> 是按顺序检查的头名列表;某个头的值不是合法 IP(比如带端口、写了 unknown)就退到下一个。想完全不看头,把 <code>ForwardedByClientIP</code> 设为 false 或 <code>RemoteIPHeaders</code> 设为 nil。注意 XFF 里带端口的写法(<code>1.2.3.4:5555</code>)不被接受。</p>'),
     ('TrustedPlatform 的风险', '<p>设置了 <code>TrustedPlatform</code>(Cloudflare、Fly.io 等)后,只要那个头非空就直接返回,不检查请求是不是真的来自该平台,也不检查内容是不是 IP。如果源站可以被绕过平台直接访问,这个头就可以任意伪造;配合防火墙只放行平台的出口 IP 才安全。</p>')],
    steps,
    [ENV_N_GIN + '。请求用 httptest 构造并直接设置 req.RemoteAddr(没有经过真实的网络);所有 IP 取自文档保留地址段(203.0.113.0/24、198.51.100.0/24、2001:db8::/32)与私有地址;每种情形各一次',
     '没有验证:真实反向代理(nginx、Cloudflare)实际发送的头格式;unix socket 监听时的“一律信任”(源码里有,见后面 unix socket 的文章);IPv6 地址在 XFF 里的写法;c.RemoteIP 与 ClientIP 在 HTTP/2 下的取值;Gin 其他版本的默认信任范围(只测了 v1.12.0)'],
    'ClientIP 与受信任代理')
